def validate_human_review_shell_v4(doc:str):
 missing=[m for m in SHELL_MARKERS if m not in doc]; forbidden=[x for x in ('service_role','SUPABASE_ACCESS_TOKEN','Authorization: Bearer') if x in doc]; return {'pass':not missing and not forbidden,'missing':missing,'forbidden':forbidden}
